request.data:
SELECT DISTINCT ?label ?description ?qid
WHERE {
  ?workflow wdt:P31 wd:Q68657 ;
            rdfs:label ?label .
  FILTER(LANG(?label) = "en")
  # data set: Objects from the Cachette de Karnak
  {
    ?workflow wdt:P1560 ?dataset_step_0a .
    ?dataset_step_0a wdt:P31 wd:Q6486603 .
    ?dataset_step_0a wdt:P1605 wd:Q6486605 .
  }
  UNION
  {
    ?workflow wdt:P1560 ?dataset_step_0b .
    ?dataset_step_0b wdt:P31 wd:Q6486603 .
    ?dataset_step_0b wdt:P1606 wd:Q6486605 .
  }
  OPTIONAL { ?workflow schema:description ?description . FILTER(LANG(?description) = "en") }
  BIND(STRAFTER(STR(?workflow), STR(wd:)) AS ?qid)
}
ORDER BY LCASE(?label)
LIMIT 101
